import unittest,re
from tools.kjv_archive import load_register,read
class RevelationCommonPraiseTests(unittest.TestCase):
 def test_common_praise_and_judgment_negation(self):
  prior,_=load_register('0.10-kjv.276');lang,manifest=load_register('0.10-kjv.277')
  self.assertEqual(prior.lexicon,{k:lang.lexicon[k] for k in prior.lexicon})
  for attr in ('pairs','suffix','prefix','possessors','roman'):self.assertEqual(getattr(prior,attr),getattr(lang,attr))
  cases={c['id'].removeprefix('revelation-'):c for c in read(lang.folder/'revelation-common-praise-cases.json')};self.assertEqual(len(cases),36)
  for c in cases.values():
   r=lang.compile(c['analysis']);self.assertEqual(c['expectedText'],r['text']);self.assertEqual(c['expectedGloss'],r['gloss']);self.assertNotIn('!',r['text'])
   self.assertFalse({'one','matter','worship'}-{'worship'}&set(r['keys']))
  anchors={'19:1': ['much people great voice', 'kjv_alleluia_revelation', 'salvation and glory and honour and power', 'lord ourone/god'], '19:2': ['true and kjv_righteous', 'earth with her/kjv_fornication corrupt:pa', 'his/servant:pl blood kjv_avenge:perf'], '19:3': ['again they kjv_alleluia_revelation', 'forever and forever'], '19:4': ['two+twelve kjv_elder:pl and four beast:pl', 'amen kjv_alleluia_revelation'], '19:5': ['ourone/god praise:imp', 'all you his/servant:pl', 'both small and great'], '19:6': ['as great kjv_multitude voice', 'as many water:pl voice', 'as mighty thunder:ev:pl voice', 'lord god kjv_almighty rule:pr'], '19:7': ['wesg glad be:opt and rejoice:opt and to he honour give:opt', 'his/wife herself ready make:perf'], '19:8': ['fine linen clean and white', 'holy person:pl kjv_righteousness'], '19:9': ['he to i write:imp', 'kjv_lamb marriage supper', 'and he to i these god true say:ev:pl'], '19:10': ['i thy/kjv_fellowservant_revelation', 'thou it do:neg:imp', 'god kjv_worship:imp', 'kjv_jesus_matthew testimony kjv_prophesy:ev spirit'], '19:11': ['white horse', 'faithful and true', 'in kjv_righteousness judge:pr and war make:pr'], '19:12': ['as fire flame', 'many crown:pl', 'no man know:pa except he himself'], '19:13': ['in blood kjv_dip_liquid:psv:pp', 'his/name god word'], '19:14': ['army:pl which in heaven', 'white horse:pl', 'fine linen white and clean'], '19:15': ['out of his/mouth sharp sword', 'with iron rod', 'kjv_almighty god fierce:ev and wrath kjv_winepress'], '19:16': ['on his/garment and on his/thigh', 'king:pl king and lord:pl lord'], '19:17': ['angel in sun', 'to all bird:pl', 'great god supper'], '19:18': ['king:pl flesh and captain:pl flesh and mighty man:pl flesh', 'horse:pl flesh', 'they who upon they sit:pr flesh', 'all man:pl flesh both free and slave:pl both small and great'], '19:19': ['beast and earth king:pl and their/army:pl', 'against he who upon horse sit:pa and against his/army'], '19:20': ['false prophet', 'beast mark receive:perf', 'his/image kjv_worship:pa', 'both these:du alive', 'with kjv_brimstone burn:cv'], '19:21': ['he who upon horse sit:pa sword', 'out of his/mouth', 'all bird:pl with their/flesh'], '20:1': ['angel from heaven down come:cv', 'kjv_bottomless_pit_revelation key', 'in his/hand great chain'], '20:2': ['that old serpent who devil and satan', 'thousand year:pl he:a bind:pa'], '20:3': ['upon he seal set:pa', 'nation:pl no more deceive:should', 'until thousand year:pl', 'little season loose:psv:must'], '20:4': ['throne:pl', 'judge:ev to they give:psv:pa', 'kjv_jesus_matthew witness and for god word', 'kjv_behead_revelation:psv:pa', 'kjv_worship:neg:perf', 'neither his/mark', 'receive:neg:perf', 'with kjv_christ_title thousand year:pl rule:pa'], '20:5': ['again live:neg:pa', 'until thousand year:pl', 'this first kjv_resurrection'], '20:6': ['first kjv_resurrection', 'second death power have:neg:pr', 'god and kjv_christ_title priest:pl', 'thousand year:pl rule:fu'], '20:7': ['thousand year:pl expire:perf', 'satan out of his/prison'], '20:8': ['earth four kjv_direction_quarter:pl', 'kjv_gog_revelation and kjv_magog_revelation', 'whose kjv_number:ev as sea sand'], '20:9': ['holy person:pl kjv_camp_site_revelation and beloved city', 'from god out of heaven fire'], '20:10': ['fire and kjv_brimstone kjv_lake_fire_revelation', 'where beast and false prophet be:pr', 'day and night forever and forever'], '20:11': ['great white throne', 'earth and heaven away flee:pa', 'for they no place'], '20:12': ['dead:pl small and great before god', 'other book', 'life book', 'kjv_according their/work:pl'], '20:13': ['sea dead:pl', 'death and hell dead:pl', 'each man kjv_according their/work:pl'], '20:14': ['death and hell into fire kjv_lake_fire_revelation', 'this second death'], '20:15': ['in life book write:psv:pp find:psv:neg:pa', 'fire kjv_lake_fire_revelation']}
  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('wesg glad be:opt',cases['19-7']['analysis'])
  self.assertIn('i thy/kjv_fellowservant_revelation',cases['19-10']['analysis'])
  self.assertIn('both these:du alive',cases['19-20']['analysis'])
  self.assertIn('kjv_worship:neg:perf',cases['20-4']['analysis'])
  self.assertIn('receive:neg:perf',cases['20-4']['analysis'])
  self.assertIn('before god',cases['20-12']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),6)
  self.assertEqual(manifest['baseForgeHead'],read(prior.folder/'manifest.json')['forgeHead'])
